parameters.jsCode:
const input = $input.item.json;

// MCP Client returns the specialist inside content[0].text
let raw = "";

if (input.content?.[0]?.text) {
  raw = input.content[0].text.trim();
} else if (input.result) {
  raw = String(input.result).trim();
} else if (input.specialist) {
  raw = String(input.specialist).trim();
}

// Convert MCP specialist names to your canonical names
const CANONICAL = {
  "Cardiologist": "Cardiology",
  "Cardiology": "Cardiology",

  "Pulmonologist": "Pulmonology",
  "Pulmonology": "Pulmonology",

  "Neurologist": "Neurology",
  "Neurology": "Neurology",

  "Gastroenterologist": "Gastroenterology",
  "Gastroenterology": "Gastroenterology",

  "Dermatologist": "Dermatology",
  "Dermatology": "Dermatology",

  "General Practitioner": "General Medicine",
  "General Medicine": "General Medicine"
};

const canonical = CANONICAL[raw] || "General Medicine";

return {
  json: {
    ...input,
    specialist_raw: raw,
    specialist: canonical
  }
};

